    case .constant:
        switch n {
        case 1: bfExpand0Lanes1(&st)
        case 2: bfExpand0Lanes2(&st)
        case 3: bfExpand0Lanes3(&st)
        case 4: bfExpand0Lanes4(&st)
        case 5: bfExpand0Lanes5(&st)
        case 6: bfExpand0Lanes6(&st)
        default: fatalError("no bcrypt kernel for \(n) lanes")
        }
    #if arch(x86_64)
    case .shrx:
        switch n {
        case 1: bfExpand0ShrxLanes1(&st)
        case 2: bfExpand0ShrxLanes2(&st)
        case 3: bfExpand0ShrxLanes3(&st)
        case 4: bfExpand0ShrxLanes4(&st)
        case 5: bfExpand0ShrxLanes5(&st)
        case 6: bfExpand0ShrxLanes6(&st)
        default: fatalError("no bcrypt kernel for \(n) lanes")
        }
    #endif
    }
}

