/// F of lane `k`, its S-boxes read in place.
@inline(__always) private func bfFShrx<let m: Int>(_ st: borrowing InlineArray<m, BfState>, _ k: Int, _ x: UInt32, _ by24: UInt32, _ by16: UInt32) -> UInt32 {
    ((st[k].s[Int(x &>> by24)] &+ st[k].s[256 + Int(x &>> by16 & 0xFF)]) ^ st[k].s[512 + Int(x >> 8 & 0xFF)])
        &+ st[k].s[768 + Int(x & 0xFF)]
}

/// One Blowfish encryption in each of 1 lane(s): `L ^= P[0]`, sixteen half-rounds `y ^= P[r] ^ F(x)`, then
/// `(L, R) = (R ^ P[17], L)` (the order bc_expand0 runs them in).
@inline(__always) private func bfEncipherShrx1<let m: Int>(_ st: borrowing InlineArray<m, BfState>,
    _ l0: inout UInt32, _ r0: inout UInt32, _ by24: UInt32, _ by16: UInt32) {
    l0 ^= st[0].p[0]
    r0 ^= st[0].p[1]
    r0 ^= bfFShrx(st, 0, l0, by24, by16)
    l0 ^= st[0].p[2]
    l0 ^= bfFShrx(st, 0, r0, by24, by16)
    r0 ^= st[0].p[3]
    r0 ^= bfFShrx(st, 0, l0, by24, by16)
    l0 ^= st[0].p[4]
    l0 ^= bfFShrx(st, 0, r0, by24, by16)
    r0 ^= st[0].p[5]
    r0 ^= bfFShrx(st, 0, l0, by24, by16)
    l0 ^= st[0].p[6]
    l0 ^= bfFShrx(st, 0, r0, by24, by16)
    r0 ^= st[0].p[7]
    r0 ^= bfFShrx(st, 0, l0, by24, by16)
    l0 ^= st[0].p[8]
    l0 ^= bfFShrx(st, 0, r0, by24, by16)
    r0 ^= st[0].p[9]
    r0 ^= bfFShrx(st, 0, l0, by24, by16)
    l0 ^= st[0].p[10]
    l0 ^= bfFShrx(st, 0, r0, by24, by16)
    r0 ^= st[0].p[11]
    r0 ^= bfFShrx(st, 0, l0, by24, by16)
    l0 ^= st[0].p[12]
    l0 ^= bfFShrx(st, 0, r0, by24, by16)
    r0 ^= st[0].p[13]
    r0 ^= bfFShrx(st, 0, l0, by24, by16)
    l0 ^= st[0].p[14]
    l0 ^= bfFShrx(st, 0, r0, by24, by16)
    r0 ^= st[0].p[15]
    r0 ^= bfFShrx(st, 0, l0, by24, by16)
    l0 ^= st[0].p[16]
    l0 ^= bfFShrx(st, 0, r0, by24, by16)
